import React, { createContext, useState, useContext } from 'react';

const TooltipContext = createContext();

const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const openTooltip = (tooltip) => {
    setTooltip(tooltip);
  };

  const closeTooltip = () => {
    setTooltip(null);
  };

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, tooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

const useTooltip = () => useContext(TooltipContext);

const Tooltip = ({ children, tooltip }) => {
  const { openTooltip, closeTooltip } = useTooltip();

  const handleMouseOver = () => {
    openTooltip(tooltip);
  };

  const handleMouseOut = () => {
    closeTooltip();
  };

  return (
    <div onMouseOver={handleMouseOver} onMouseOut={handleMouseOut}>
      {children}
      {tooltip && (
        <div className="tooltip">
          <p>{tooltip}</p>
        </div>
      )}
    </div>
  );
};

const App = () => {
  return (
    <TooltipProvider>
      <Tooltip tooltip="This is a tooltip">
        <button>Hover me</button>
      </Tooltip>
      <Tooltip tooltip="This is another tooltip">
        <button>Hover me again</button>
      </Tooltip>
    </TooltipProvider>
  );
};
```

