import { Worker } from 'worker_threads';

export default class CsvDownloaderService {
  async downloadCsv(csvData) {
    const worker = new Worker('./workers/csv-downloader-worker.js', {
      workerData: csvData,
    });

    return new Promise((resolve, reject) => {
      worker.on('message', (data) => {
        resolve(data);
      });

      worker.on('error', (error) => {
        reject(error);
      });

      worker.on('exit', () => {
        worker.terminate();
      });
    });
  }
}
